// Large s-interpolations must not overflow the compiler's stack (scala/bug#10870),
// and each concatenation chunk must stay a String concatenation even when the
// splices are not Strings (scala/bug#11665).
object Test:
  val i: Int = 1
  val s: String = "s"

  def expected(nparts: Int): String =
    val sb = new StringBuilder
    sb.append(if 0 % 3 == 0 then "" else ".")
    for k <- 1 until nparts do
      sb.append(if (k - 1) % 2 == 0 then i else s)
      sb.append(if k % 3 == 0 then "" else ".")
    sb.toString

